"""Gera as 30 páginas estáticas. Sem dependências nem serviços externos."""
import html, json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'src'
OUT.mkdir(exist_ok=True)
def esc(value):return html.escape(str(value),quote=True)
datasets=[json.loads((ROOT/'content'/f'{name}.json').read_text()) for name in ('personal','logistics','places','life')]
pages={p['slug']:p for d in datasets for p in d['pages']}
order=['index','antes-de-partir','tsinghua','estudos-ist','vida-campus','entrada-vistos','voos-aeroportos','dinheiro-pagamentos','internet-telemovel','apps','quando-ir','bairros','alojamento','metro-autocarros','taxis-bicicletas','comboios-excursoes','cidade-proibida-tiananmen','grande-muralha','palacios-templos','hutongs-parques','museus-arte','gastronomia','lingua','compras','saude','seguranca-emergencias','itinerarios','orcamento','mala-checklist','fontes']
assert set(order)==set(pages) and len(order)==30,'O guia deve ter exatamente 30 páginas.'
groups=[('preparar','Antes de partir',['antes-de-partir','entrada-vistos','voos-aeroportos','quando-ir','mala-checklist']),('estudar','Na Tsinghua',['tsinghua','estudos-ist','vida-campus','alojamento']),('viver','Viver em Pequim',['dinheiro-pagamentos','internet-telemovel','apps','bairros','gastronomia','lingua','compras','saude','seguranca-emergencias']),('mover','Ir mais longe',['metro-autocarros','taxis-bicicletas','comboios-excursoes']),('explorar','Descobrir a cidade',['cidade-proibida-tiananmen','grande-muralha','palacios-templos','hutongs-parques','museus-arte','itinerarios']),('planear','O teu plano',['orcamento','fontes'])]
category={s:(id,label) for id,label,slugs in groups for s in slugs}
category['index']=('inicio','Começar')
sources={}
aliases={}
url_to_id={}
for d in datasets:
 for s in d['sources']:
  url=s['url'].rstrip('/').replace('https://www.is.tsinghua.edu.cn','https://is.tsinghua.edu.cn')
  if url in url_to_id:aliases[s['id']]=url_to_id[url]
  else:
   url_to_id[url]=s['id'];aliases[s['id']]=s['id'];sources[s['id']]=s
related_aliases={'vistos':'entrada-vistos','roteiros':'itinerarios','transportes':'metro-autocarros'}
for p in pages.values():
 p['related']=list(dict.fromkeys(related_aliases.get(s,s) for s in p.get('related',[])))
 for section in p['sections']:
  for sid in section.get('sourceIds',[]):assert sid in aliases,(p['slug'],sid)
 for rel in p.get('related',[]):assert rel in pages,(p['slug'],rel)
words=sum(len(' '.join([p['description']]+[str(t) for s in p['sections'] for t in s.get('paragraphs',[])+s.get('bullets',[])]).split()) for p in pages.values())
word_label=f'{words:,}'.replace(',', '.')
for i,s in enumerate(order):
 pages[s]['number']=f'{i:02d}'
 pages[s]['group']=category[s][0]
 pages[s]['groupLabel']=category[s][1]
 pages[s]['readMinutes']=max(2,round(sum(len(' '.join(x.get('paragraphs',[])+x.get('bullets',[])).split()) for x in pages[s]['sections'])/180))
icons={
 'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 'search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
 'book':'<path d="M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v15"/>',
 'bookmark':'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',
 'check':'<path d="m5 12 4 4L19 6"/>',
 'compass':'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5 5-3Z"/>',
 'sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
 'globe':'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-6 5-6 13 0 18 6-5 6-13 0-18Z"/>',
 'menu':'<path d="M4 6h16M4 12h16M4 18h16"/>',
 'close':'<path d="m6 6 12 12M6 18 18 6"/>',
 'print':'<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6Z"/>',
 'wallet':'<path d="M3 7V5h17v15H3V7Zm0 2h17m-5 5h5m-4 0h1"/>',
 'plane':'<path d="m3 10 7 2 9-9 2 2-9 9 2 7-3 1-3-7-5-2 0-3Z"/>',
 'school':'<path d="m2 9 10-6 10 6-10 6-10-6Zm4 3v6c4 3 8 3 12 0v-6m4-3v9"/>',
}
def icon(name):return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{icons[name]}</svg>'
def href(slug):return f'{slug}.html'
def link(slug,cls='',label=None):return f'<a class="{cls}" href="{href(slug)}">{esc(label or pages[slug]["title"])}{icon("arrow") if cls in ("text-link","button") else ""}</a>'
def source_links(ids):
 ids=list(dict.fromkeys(aliases[id] for id in ids))
 return '<div class="citations"><span>Consultar</span>'+''.join(f'<a href="{esc(sources[id]["url"])}" target="_blank" rel="noopener">{esc(sources[id]["publisher"])} · {esc(sources[id]["title"])} ↗</a>' for id in ids)+'</div>' if ids else ''
def nav(slug):
 return '<a class="skip" href="#main">Saltar para o conteúdo</a><header class="header"><div class="header-inner"><a href="index.html" class="brand" aria-label="Pequim · início"><span class="seal" lang="zh">北<br>京</span><span>pequim<span class="brand-dot">.</span><small>GUIA DE UM SEMESTRE</small></span></a><nav class="top-nav" aria-label="Navegação principal">'+''.join(f'<a {"aria-current=page" if category[slug][0]==id else ""} href="index.html#grupo-{id}">{label}</a>' for id,label in [('preparar','Preparar'),('estudar','Estudar'),('viver','Viver'),('explorar','Explorar')])+f'</nav><div class="header-actions"><button class="search-trigger" data-open-search>{icon("search")}<span>Pesquisar</span><kbd>⌘ K</kbd></button><button class="plan-trigger" data-open-plan>{icon("bookmark")}<span>O meu plano</span></button><button class="mobile-menu icon-button" data-open-menu aria-label="Abrir índice">{icon("menu")}</button></div></div></header><div class="reading-progress" aria-hidden="true"><span></span></div>'
def dialogs():
 return f'''<dialog id="search-dialog"><div class="dialog-heading"><span class="eyebrow">O guia inteiro, à distância de uma pergunta</span><button class="icon-button" data-close aria-label="Fechar pesquisa">{icon('close')}</button></div><label class="search-field">{icon('search')}<input id="global-search" type="search" placeholder="Visto, cantinas, Compiladores, Muralha…" aria-label="Pesquisar em todas as páginas"></label><p id="search-status" class="muted" role="status"></p><div id="search-results"></div></dialog>
 <dialog id="plan-dialog"><div class="dialog-heading"><div><span class="eyebrow">GUARDADO NESTE NAVEGADOR</span><h2>O teu plano.</h2></div><button class="icon-button" data-close aria-label="Fechar plano">{icon('close')}</button></div><div class="plan-stats"><div><strong id="saved-count">0</strong>favoritos</div><div><strong id="read-count">0</strong>páginas lidas</div><div><strong id="check-count">0</strong>tarefas feitas</div></div><div id="saved-pages"></div><div class="plan-quick"><a href="mala-checklist.html">Abrir checklist ↗</a><a href="orcamento.html">Abrir orçamento ↗</a></div><label class="form-label" for="personal-notes">Notas e perguntas pendentes</label><textarea id="personal-notes" rows="4" placeholder="Perguntar ao coordenador sobre Compiladores…"></textarea><p class="tiny">As notas ficam locais. Evita guardar documentos ou números de identificação.</p><div class="backup-actions"><button class="button" id="export-plan">Exportar plano ↓</button><label class="button secondary" for="import-plan">Importar plano ↑</label><input type="file" accept="application/json,.json" id="import-plan" hidden></div></dialog>
 <dialog id="menu-dialog"><div class="dialog-heading"><h2>30 páginas. Um semestre.</h2><button class="icon-button" data-close aria-label="Fechar índice">{icon('close')}</button></div>{guide_groups()}</dialog><div id="toast" role="status" aria-live="polite"></div>'''
def guide_groups():
 return ''.join(f'<div class="menu-group"><span class="eyebrow">{esc(label)}</span>'+''.join(link(slug,'menu-link',f'{pages[slug]["number"]} · {pages[slug]["title"]}') for slug in slugs)+'</div>' for id,label,slugs in groups)
def footer():
 return f'<footer class="footer"><div><a class="footer-brand" href="index.html">pequim.</a><p>Um semestre de descobertas.<br>Do Técnico à Tsinghua, primavera de 2027.</p></div><div><span class="eyebrow">O TEU GUIA LOCAL</span><p>30 páginas · {len(sources)} fontes · {word_label} palavras</p><p>Pesquisa: 04.10.2026 · Confirmar regras para 2027.</p><a href="fontes.html">Fontes e créditos ↗</a></div><div><span class="eyebrow">COMEÇA PELO ESSENCIAL</span><a href="estudos-ist.html">Equivalências no IST</a><a href="entrada-vistos.html">Documentos e visto de estudo</a><a href="mala-checklist.html">A tua checklist</a></div><div class="footer-bottom">FEITO PARA EXPLORAR COM TEMPO<span>北京 · PEQUIM · BEIJING</span></div></footer>'
