def sidebar(p):
 return '<aside class="article-sidebar"><a class="back-link" href="index.html#guia">← Todos os temas</a><span class="eyebrow">NESTA PÁGINA</span><nav aria-label="Índice da página">'+''.join(f'<a href="#sec-{i+1}">{esc(s["title"])}</a>' for i,s in enumerate(p['sections']))+'</nav><div class="sidebar-box"><span class="eyebrow">ANTES DE CONTINUAR</span><p>Regras e serviços podem mudar até 2027. Confirma os pontos decisivos com as fontes.</p><a href="fontes.html">Ver metodologia ↗</a></div></aside>'
def body_section(s,i):
 result=f'<section id="sec-{i+1}" class="article-section"><span class="section-number">{i+1:02d}</span><h2>{esc(s["title"])}</h2>'
 result+=''.join(f'<p>{esc(p)}</p>' for p in s.get('paragraphs',[]))
 if s.get('bullets'):result+='<ul>'+''.join(f'<li>{esc(b)}</li>' for b in s['bullets'])+'</ul>'
 if s.get('image'):result+=f'<figure class="article-figure"><a href="{esc(s["image"])}" target="_blank"><img src="{esc(s["image"])}" alt="{esc(s.get("caption",s["title"]))}" loading="lazy"></a><figcaption>{esc(s.get("caption",""))}</figcaption></figure>'
 return result+source_links(s.get('sourceIds',[]))+'</section>'
def tools(slug):
 if slug=='orcamento':return budget()
 if slug=='mala-checklist':return checklist()
 if slug=='fontes':return source_directory()
