def budget():
 fields=[('days','Dias na China',150,'dias',1,366),('rate','CNY por 1 euro',7.6,'CNY / EUR',0.01,100),('housing','Alojamento mensal',900,'CNY',0,100000),('food','Alimentação mensal',1500,'CNY',0,50000),('transport','Transportes mensais',300,'CNY',0,50000),('phone','Telefone mensal',120,'CNY',0,50000),('leisure','Lazer mensal',600,'CNY',0,50000),('travel','Fundo de viagens mensal',900,'CNY',0,100000),('other','Outros custos mensais',300,'CNY',0,50000),('flight','Voos e bagagem',900,'EUR · custo único',0,50000),('documents','Visto, seguro e documentos',1200,'CNY · custo único',0,100000),('setup','Instalação e cauções',1500,'CNY · custo único',0,100000),('reserve','Reserva de emergência',10000,'CNY · separada',0,1000000)]
 return '<section class="widget budget-widget" id="simulador"><div class="widget-heading"><div><span class="eyebrow">FERRAMENTA LOCAL</span><h2>Simular o semestre.</h2></div>'+icon('wallet')+'</div><p>Valores iniciais = hipóteses de planeamento. Usa propostas reais quando as tiveres. Mês de cálculo = 30 dias.</p><div class="budget-presets" role="group" aria-label="Cenários de orçamento"><button data-preset="economico">Campus · triplo</button><button data-preset="confortavel">Campus · duplo</button><button data-preset="fora">Fora do campus</button></div><div class="budget-grid"><form id="budget-form">'+''.join(f'<label class="budget-field"><span>{label}</span><div><input name="{id}" type="number" value="{value}" min="{minv}" max="{maxv}" step="{0.01 if id=="rate" else 1}" required><small>{unit}</small></div></label>' for id,label,value,unit,minv,maxv in fields)+'</form><div class="budget-result" aria-live="polite"><span class="eyebrow">TOTAL COM RESERVA</span><strong id="budget-total">—</strong><span id="budget-cny">—</span><div id="budget-breakdown"></div><p class="tiny">Inclui a reserva, que não é despesa prevista. Cauções são liquidez bloqueada. O câmbio é uma hipótese editável.</p><button class="button secondary" id="budget-reset">Repor valores iniciais</button></div></div><p class="tiny">30/40 CNY por dia são referências publicadas para os quartos de intercâmbio; tarifas finais e atribuição devem ser confirmadas. Os outros valores são pressupostos, não preços pesquisados.</p></section>'
CHECKS={
 'Académico':['Confirmar colocação e nomeação pelo IST','Receber link e instruções da candidatura Tsinghua','Confirmar categoria do intercâmbio','Enviar candidatura e guardar comprovativo','Confirmar línguas e acesso às cadeiras','Resolver Compiladores com o coordenador','Aprovar Learning Agreement e alternativas','Confirmar calendário de acolhimento e avaliações'],
 'Documentos e saúde':['Verificar validade e dados do passaporte','Receber admissão e documentos de estudo','Confirmar e pedir o visto adequado','Confirmar regras de reentrada','Contratar seguro exigido e guardar assistência','Preparar consulta de medicina do viajante','Confirmar documentação de medicação','Guardar cópias offline dos documentos'],
 'Alojamento e dinheiro':['Reservar residência ou alternativa verificável','Confirmar data de entrada e saída do quarto','Guardar morada e portão em chinês','Planear registo de alojamento','Simular orçamento com alternativa fora do campus','Testar cartão e carteira de pagamentos','Preparar meio de pagamento independente','Reservar liquidez de emergência'],
 'Mundo digital e mala':['Confirmar telefone desbloqueado e compatibilidade','Planear número português e SIM local','Preparar SMS e recuperação de contas','Testar ferramentas e recursos académicos','Descarregar mapas e traduções offline','Fazer cópias de segurança','Preparar roupas de frio e calor','Confirmar tomadas, carregadores e baterias aéreas'],
 'Chegada e regresso':['Comprar voo com condições claras','Confirmar transfer e primeira noite','Avisar contacto em Portugal da chegada','Tratar de cartão, matrícula e rede do campus','Guardar alterações aprovadas e avaliações','Pedir transcript e documentos finais','Verificar saída da residência e caução','Encerrar serviços e entregar documentos no IST']}
def checklist():
 return '<section class="widget checklist-widget" id="checklist"><div class="widget-heading"><div><span class="eyebrow">40 TAREFAS · PROGRESSO LOCAL</span><h2>A tua checklist.</h2></div><strong id="checklist-progress">0 / 40</strong></div><div class="check-progress"><span></span></div>'+''.join(f'<fieldset><legend>{label}</legend>'+''.join(f'<label class="check-item"><input type="checkbox" data-check="{groupid}-{i}"><span>{esc(text)}</span></label>' for i,text in enumerate(items))+'</fieldset>' for groupid,(label,items) in enumerate(CHECKS.items()))+'</section>'
def source_directory():
 items=''.join(f'''<article class="source-item" id="fonte-{esc(s["id"])}" data-source-search="{esc(s["title"]+" "+s["publisher"]+" "+s["note"])}"><span class="eyebrow">{esc(s["publisher"])}</span><h3><a href="{esc(s["url"])}" target="_blank" rel="noopener">{esc(s["title"])} ↗</a></h3><p>{esc(s["note"])}</p><small>Consultada em {esc(s["checked"])} · <span>{esc(s["url"].split('/')[2] if s["url"].startswith('http') else 'Documento local')}</span></small></article>''' for s in sources.values())
 return f'''<section class="widget source-directory" id="diretorio"><span class="eyebrow">BIBLIOTECA DE PESQUISA</span><h2>{len(sources)} fontes, sempre à mão.</h2><label class="search-field">{icon('search')}<input type="search" id="source-filter" placeholder="Pesquisar entidade ou assunto…" aria-label="Filtrar fontes"></label><p id="source-count" class="muted" role="status">{len(sources)} fontes</p>{items}<p id="source-empty" hidden>Nenhuma fonte encontrada.</p></section><section class="widget"><h2>Documentos institucionais.</h2><div class="document-links"><a href="https://intl-nondegree.tsinghua.edu.cn/b/yzlxs/yz_sys_xxfjb/download/file?id=532132" target="_blank" rel="noopener">Programa oficial · Spring 2027 ↗</a><a href="https://intl-nondegree.tsinghua.edu.cn/b/yzlxs/yz_sys_xxfjb/download/file?id=501383" target="_blank" rel="noopener">Catálogo graduate · Spring 2026 ↗</a><a href="https://intl-nondegree.tsinghua.edu.cn/b/yzlxs/yz_sys_xxfjb/download/file?id=501384" target="_blank" rel="noopener">Catálogo undergraduate · Spring 2026 ↗</a><a href="https://www.tsinghua.edu.cn/zjqh/syxx/qhxl.htm" target="_blank" rel="noopener">Calendário institucional ↗</a><a href="guia-completo.md">Todo o guia em Markdown ↓</a></div></section><section class="widget photo-credits"><h2>Créditos visuais.</h2><p>Cidade Proibida: <a href="https://commons.wikimedia.org/wiki/File:Forbidden_City_panorama_from_Gate_of_Supreme_Harmony.jpg">Daniel Case</a>, <a href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a>. Tsinghua: <a href="https://commons.wikimedia.org/wiki/File:Street_in_front_of_former_gate_of_Tsinghua_University.JPG">Soramimi (そらみみ)</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Templo do Céu: <a href="https://commons.wikimedia.org/wiki/File:Temple_Of_Heaven.jpg">BIJAY BHANDARI</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Imagens redimensionadas; o layout recorta o enquadramento. As adaptações destas fotografias mantêm a respetiva licença.</p></section>'''
def article(slug):
 p=pages[slug];i=order.index(slug)
 header=f'<div class="article-heading wrap"><div class="breadcrumb"><a href="index.html">Pequim</a> / <span>{esc(p["groupLabel"])}</span> / {p["number"]}</div><span class="eyebrow">{p["number"]} / {esc(p["groupLabel"])}</span><h1>{esc(p["title"])}</h1><p class="article-description">{esc(p["description"])}</p><div class="article-meta"><span>{p["readMinutes"]} min de leitura</span><span>Pesquisa · 04 outubro 2026</span><button data-save="{slug}" class="save-article" aria-pressed="false">{icon("bookmark")} <span>Guardar página</span></button><button class="icon-button" data-print aria-label="Imprimir esta página">{icon("print")}</button></div></div>'
 intro='<div class="takeaways"><span class="eyebrow">O QUE VALE A PENA RETER</span>'+''.join(f'<p>{icon("check")}{esc(t)}</p>' for t in p['takeaways'])+'</div>'
 related='<div class="related"><span class="eyebrow">CONTINUA A EXPLORAR</span><h2>Vale a pena ligar os pontos.</h2><div>'+''.join(link(s,'text-link') for s in p['related'])+'</div></div>'
 return '<main id="main">'+header+'<div class="article-layout wrap">'+sidebar(p)+'<article class="article-body">'+intro+tools(slug)+''.join(body_section(s,j) for j,s in enumerate(p['sections']))+f'<div class="read-finish"><button class="button secondary" data-mark-read="{slug}">{icon("check")} Marcar como lida</button><p>O progresso fica guardado no teu navegador.</p></div>'+related+'</article></div><nav class="page-pagination wrap" aria-label="Páginas anterior e seguinte">'+link(order[i-1],label='← '+pages[order[i-1]]['title'])+(link(order[i+1],label=pages[order[i+1]]['title']+' →') if i<29 else link('index',label='Voltar ao início →'))+'</nav></main>'
for slug in order:
 p=pages[slug]
 doc=f'''<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(p['description'])}"><meta name="theme-color" content="#9a3c2d"><title>{esc(p['title'])} — Pequim · IST → Tsinghua</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css?v=2"><script defer src="assets/search-data.js"></script><script defer src="assets/app.js?v=2"></script></head><body data-page="{slug}">{nav(slug)}{home() if slug=='index' else article(slug)}{footer()}{dialogs()}<noscript><p class="noscript">Podes ler todas as páginas sem JavaScript. Pesquisa, favoritos, orçamento e checklist precisam de JavaScript.</p></noscript></body></html>'''
 (OUT/f'{slug}.html').write_text(doc)
search=[dict(slug=s,title=pages[s]['title'],description=pages[s]['description'],group=pages[s]['groupLabel'],number=pages[s]['number'],sections=[dict(title=x['title'],text=' '.join(x.get('paragraphs',[])+x.get('bullets',[])),anchor=f'sec-{i+1}') for i,x in enumerate(pages[s]['sections'])]) for s in order]
search[0]['sections']=[dict(title='Explorar o guia',text=pages['index']['description']+' '+pages['index']['sections'][0]['paragraphs'][1],anchor='guia')]
(OUT/'assets/search-data.js').write_text('window.BEIJING_GUIDE='+json.dumps(search,ensure_ascii=False)+';')
(OUT/'sources.json').write_text(json.dumps(list(sources.values()),ensure_ascii=False,indent=2))
md=['# Pequim · guia do teu semestre\n\nIST → Tsinghua · Spring 2027\n\nPesquisa: 4 de outubro de 2026. Reconfirmar condições individuais e regras de 2027.\n']
for slug in order:
 p=pages[slug];md.append(f'\n# {p["number"]} · {p["title"]}\n\n{p["description"]}\n')
 for s in p['sections']:
  md.append('\n## '+s['title']+'\n\n'+'\n\n'.join(s.get('paragraphs',[]))+'\n')
  md.extend('- '+b+'\n' for b in s.get('bullets',[]))
  for id in dict.fromkeys(aliases[x] for x in s.get('sourceIds',[])):
   x=sources[id];md.append(f'\nFonte: [{x["publisher"]} · {x["title"]}]({x["url"]})\n')
md.append('\n# Diretório de fontes\n')
md.extend(f'\n- [{s["title"]}]({s["url"]}) · {s["publisher"]} · {s["checked"]}. {s["note"]}\n' for s in sources.values())
(OUT/'guia-completo.md').write_text(''.join(md))
(OUT/'assets/guide-metrics.json').write_text(json.dumps(dict(pages=30,sources=len(sources),words=words,sections=sum(len(p['sections']) for p in pages.values()),slugs=order),indent=2))
print(f'Criadas 30 páginas; {len(sources)} fontes distintas; {word_label} palavras; {sum(len(p["sections"]) for p in pages.values())} secções.')
